TLM.f("Sancti/05-02",{"officium":"S. Athanasii Confessoris Ecclesiæ Doctoris","rule":["Gloria","CredoDA"],"ruleInherited":["Gloria"],"fallback":"Commune/C4a","from":{"GradualeP":"Commune/C4a","Tractus":"Commune/C4a"},"sections":{"Introitus":[{"k":"ref","la":"Eccli 15:5"},{"k":"text","la":"In médio Ecclésiæ apéruit os ejus: et implévit eum Dóminus spíritu sapiéntiæ et intelléctus: stolam glóriæ índuit eum, allelúja, allelúja."},{"k":"ref","la":"Ps 91:2"},{"k":"text","la":"Bonum est confitéri Dómino: et psállere nómini tuo, Altíssime."},{"k":"macro","name":"Gloria"},{"k":"text","la":"In médio Ecclésiæ apéruit os ejus: et implévit eum Dóminus spíritu sapiéntiæ et intelléctus: stolam glóriæ índuit eum, allelúja, allelúja."}],"Oratio":[{"k":"text","la":"Exáudi, quǽsumus, Dómine, preces nostras, quas in beáti Athanásii Confessóris tui atque Pontíficis solemnitáte deférimus: et, qui tibi digne méruit famulári, ejus intercedéntibus méritis, ab ómnibus nos absólve peccátis."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Corínthios."},{"k":"ref","la":"2 Cor 4:5-14"},{"k":"text","la":"Fratres: Non nosmetípsos prædicámus, sed Jesum Christum, Dóminum nostrum: nos autem servos vestros per Jesum: quóniam Deus, qui dixit de ténebris lucem splendéscere, ipse illúxit in córdibus nostris ad illuminatiónem sciéntiæ claritátis Dei, in fácie Christi Jesu. Habémus autem thesáurum istum in vasis fictílibus: ut sublímitas sit virtútis Dei, et non ex nobis. In ómnibus tribulatiónem pátimur, sed non angustiámur: aporiámur, sed non destitúimur: persecutiónem pátimur, sed non derelínquimur: dejícimur, sed non perímus: semper mortificatiónem Jesu in córpore nostro circumferéntes, ut et vita Jesu manifestétur in corpóribus nostris. Semper enim nos, qui vívimus, in mortem trádimur propter Jesum: ut et vita Jesu manifestétur in carne nostra mortáli. Ergo mors in nobis operátur, vita autem in vobis. Habéntes autem eúndem spíritum fídei, sicut scriptum est: Crédidi, propter quod locútus sum: et nos crédimus, propter quod et lóquimur: sciéntes, quóniam qui suscitávit Jesum, et nos cum Jesu suscitábit et constítuet vobíscum."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 109:4"},{"k":"text","la":"Tu es sacérdos in ætérnum, secúndum órdinem Melchísedech. Allelúja"},{"k":"ref","la":"Jas 1:12"},{"k":"text","la":"Beátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Eccli 45:9"},{"k":"text","la":"Amávit eum Dóminus, et ornávit eum: stolam glóriæ índuit eum."},{"k":"ref","la":"Osee 14:6"},{"k":"text","la":"Justus germinábit sicut lílium: et florébit in ætérnum ante Dóminum. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 36:30-31"},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium."},{"k":"text","la":"Lex Dei ejus in corde ipsíus: et non supplantabúntur gressus ejus.","mark":"V"},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum."},{"k":"ref","la":"Matt 10:23-28"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Cum persequéntur vos in civitáte ista, fúgite in áliam. Amen dico vobis, non consummábitis civitátes Israël, donec véniat Fílius hóminis. Non est discípulus super magistrum, nec servus super dóminum suum. Súfficit discípulo, ut sit sicut magister ejus: et servo, sicut dóminus ejus. Si patremfamílias Beélzebub vocavérunt: quanto magis domésticos ejus? Ne ergo timuéritis eos. Nihil enim est opértum, quod non revelábitur: et occúltum, quod non sciétur. Quod dico vobis in ténebris, dícite in lúmine: et, quod in aure audítis, prædicáte super tecta. Et nolíte timére eos, qui occídunt corpus, ánimam autem non possunt occídere: sed pótius timéte eum, qui potest et ánimam et corpus pérdere in gehénnam."}],"Offertorium":[{"k":"ref","la":"Ps 88:21-22"},{"k":"text","la":"Invéni David servum meum, óleo sancto meo unxi eum: manus enim mea auxiliábitur ei, et bráchium meum confortábit eum, allelúja."}],"Secreta":[{"k":"text","la":"Sancti Athanásii Confessóris tui atque Pontíficis, quǽsumus, Dómine, ánnua sollémnitas pietáti tuæ nos reddat accéptos: ut, per hæc piæ placatiónis offícia, et illum beáta retribútio comitétur, ei nobis grátiæ tuæ dona concíliet."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 10:27"},{"k":"text","la":"Quod dico vobis in ténebris, dícite in lúmine, dicit Dóminus: et quod in aure audítis, prædicáte super tecta, allelúja."}],"Postcommunio":[{"k":"text","la":"Deus, fidélium remunerátor animárum: præsta; ut, beáti Athanásii Confessóris tui atque Pontíficis, cujus venerándam celebrámus festivitátem, précibus indulgéntiam consequámur."},{"k":"macro","name":"Per Dominum"}],"Graduale1":[{"k":"ref","la":"Eccli 44:16"},{"k":"text","la":"Ecce sacérdos magnus, qui in diébus suis plácuit Deo."},{"k":"ref","la":"Eccli 44:20"},{"k":"text","la":"Non est invéntus símilis illi, qui conserváret legem Excélsi. Allelúja, allelúja"},{"k":"ref","la":"Jas 1:12"},{"k":"text","la":"Beátus vir, qui suffert tentatiónem: quóniam cum probátus fúerit, accípiet corónam vitæ. Allelúja."}]},"hr":{"c970c462bacf8f65":{"t":"Sir 15, 5, Ps 91, 2\n(Sir 15, 5) Usred Crkve otvorio je Gospodin usta njegova i napunio ga duhom mudrosti i razuma, ogrnuo ga odjećom slave. <i>Aleluja</i>, <i>aleluja</i>.\n(Ps. 91, 2) Dobro je slaviti Gospodina i pjevati imenu tvojem, Višnji!\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Sir 15, 5) Usred Crkve otvorio je Gospodin usta njegova i napunio ga duhom mudrosti i razuma, ogrnuo ga odjećom slave. <i>Aleluja</i>, <i>aleluja</i>."},"cbeab2ec6ffec684":{"t":"<i>Pomolimo se</i>.\nUsliši, molimo, Gospodine, naše molitve koje ti prinosimo o svetkovini blaženog Atanazija tvoga priznavaoca i biskupa i odriješi nas od svih grijeha po zaslugama onoga koji je zavrijedio da ti dostojno služi.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"d2ffd11ca46f03e6":{"t":"2 Kor 4, 5-14\nČitanje Poslanice bl. Pavla apostola Korinćanima. Braćo, mi ne propovijedamo sami sebe, nego Isusa Krista kao svojega Gospodina, a sebe kao vaše sluge radi Isusa. Jer je Bog, na čiju je riječ iz tame zasjalo svjetlo, zapalio u našim srcima svjetlo spoznaje Božjega veličanstva na licu Isusa Krista. Ovaj zaklad nosimo u zemljanim pobudama da uzvišenost ne dolazi od nas, nego je djelo Božje moći. U svemu trpimo ostavljeni; odbacuju nas, ali ne uništavaju. Uvijek u svojem tijelu nosimo smrtne Isusove muke, da se i na našem tijelu odražava Isusov život. Uvijek se za života zbog Isusa predajemo smrti, da se Isusov život očituje na našem smrtnom tijelu. Dakle, smrt je djelotvorna u nama, u vama pak život. Imajući isti duh vjere, kao što je pisano: Vjerovao sam, zbog toga i govorim. I mi vjerujemo, zbog toga i govorimo, znajući da će onaj koji je uskrisio Isusa uskrsnuli s Isusom i naš i postaviti zajedno s vama."},"938d5ef0d65882cb":{"t":"Ps 109, 4, Jak 1, 12\n<i>Aleluja</i>, <i>aleluja</i>.\n(Ps 109, 4) Ti si svećenik dovijeka po redu Melkisedekovu. <i>Aleluja</i>.\n(Jak 1, 12) Blago čovjeku koji nadvlada napast, jer kad bude prokušan, primit će krunu života. <i>Aleluja</i>."},"bff911922829d38b":{"t":"Mt 10, 23-28\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme Isus reče svojim učenicima: Kada vas budu progonili u jednom gradu, bježite u drugi. Jamčim vam da nećete obići izraelskih gradova prije dolaska Sina Čovječjega. Učenik nije viši od učitelja niti je sluga viši od svojega gospodara. Dovoljno je, da učenik bude kao njegov učitelj, i sluga kao njegov gospodar. Ako su domaćina nazvali Belzebubom, kako će istom nazivati njegove ukućane? Vi se ne trebate bojati. Ništa nema sakrivena, što se ne bi otkrilo, ni tajna, što se ne bi saznalo. Sto vam kažem u tami, recite na svjetlu, a što čujete na uho, propovijedajte na krovovima. Nemojte se bojati onih koji ubijaju tijelo, a ne mogu ubiti duše; nego više se bojte onoga koji može i dušu i tijelo upropastiti u paklu."},"5ebabe64ecb9d6c4":{"t":"Ps 88, 21-22\nNašao sam Davida, slugu svojega, pomazao sam ga svojim svetim uljem. S njim će biti ruka moja i krijepit će ga desnica moja. <i>Aleluja</i>."},"3eca84d473a99d2c":{"t":"Godišnja svetkovina svetog Atanazija priznavaoca tvoga i biskupa neka nas, molimo, Gospodine, učini dragima tvojoj dobroti da, po ovoj smjernoj pomirbenoj službi, njega prati kao blažena nagrada i nama isprosi darove tvoje milosti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"1a0a565aa39e4fe3":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno da tebe, Gospodine, u svako doba, a osobito <i>u ovo</i> svečanije slavimo, kad je Krist žrtvovan, naše vazmeno Janje. On je naime pravo janje koje oduze grijehe svijeta. Svojom smrću on je uništio našu smrt i svojim uskrsnućem obnovio naš život. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:"},"8fba098bdf8806fd":{"t":"Mt 10, 27\nŠto vam kažem u tami, razglasujte na svjetlu, kaže Gospodin, i ono što vam na uho šapćem, propovijedajte s krovova. <i>Aleluja</i>."},"7c45caf19894838c":{"t":"<i>Pomolimo se</i>.\nBože, koji nagrađuješ duše vjernih, podaj da po molitvama blaženog Atanazija priznavaoca tvoga i biskupa, kojega časnu svetkovinu slavimo, postignemo oproštenje.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
